#![deny(clippy::all, clippy::pedantic, clippy::nursery, missing_docs, warnings)]

//! The exposed project serves declaration data from MPs in the UK parliament.

/// Contains the domain models for the project.
pub mod domain;

/// Contains the inbound adapters for the project
pub mod inbound;

/// Contains the outbound adapters for the project
pub mod outbound;
//! A collection of outbound adapters for the `exposed` project

mod declaration_ingestion;
mod entity_ingestion;
mod file_system;
mod funder;
mod parliament_api;
mod parliament_member;
mod postgres;

pub use file_system::ExposedDataPipeline;
pub use parliament_api::ParliamentApiClient;
pub use postgres::ExposedDatabase;
//! Declarations are groups of funding entries that are submitted by MPs to Parliament.

#[derive(Clone)]
/// Trigram similarity score
pub struct SearchSimilarity(f32);

impl SearchSimilarity {
    #[must_use]
    /// Trigram similarity score value
    pub const fn value(&self) -> f32 {
        self.0
    }
}

impl From<f32> for SearchSimilarity {
    fn from(value: f32) -> Self {
        Self(value)
    }
}

#[cfg(test)]
mod f64_conversion {
    use crate::domain::models::search_similarity::SearchSimilarity;

    #[test]
    fn behaves_as_expected() {
        let small = SearchSimilarity::from(1_f32);
        let big = SearchSimilarity::from(2_f32);

        assert!(big.value() > small.value());
    }

    #[test]
    fn does_not_round() {
        let small = SearchSimilarity::from(0.1_f32);
        let big = SearchSimilarity::from(0.9_f32);

        assert!(big.value() > small.value());
    }
}
