use clap::{Parser, Subcommand};
use exposed::inbound::{
    cli::{DataArgs, run_cli},
    http::{config::ServerConfig, server::serve_exposed},
};
use tokio::net::TcpListener;

#[derive(Parser)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    Server,
    Data(DataArgs),
}

fn main() -> anyhow::Result<()> {
    let args = Cli::parse();
    if matches!(args.command, Commands::Server) {
        dotenvy::dotenv().ok();
    }
    run(args)
}

#[tokio::main]
async fn run(args: Cli) -> anyhow::Result<()> {
    match args.command {
        Commands::Server => {
            let config = ServerConfig::from_env()?;
            let listener = match TcpListener::bind("0.0.0.0:6999").await {
                Err(error) if error.kind() == std::io::ErrorKind::AddrInUse => {
                    TcpListener::bind("0.0.0.0:0").await?
                }
                result => result?,
            };
            println!(
                "Listening on http://localhost:{}",
                listener.local_addr()?.port()
            );
            serve_exposed(&config, listener).await?;
        }
        Commands::Data(args) => run_cli(args).await?,
    }

    Ok(())
}
use std::sync::Arc;

use tokio::net::TcpListener;

use crate::{
    domain::services::entity_search::Service as EntitySearchService,
    inbound::http::{config::ServerConfig, routes::routes, state::AppState},
    outbound::ExposedDatabase,
};

/// Starts an `exposed` HTTP server
///
/// # Errors
/// - When the HTTP server fails
pub async fn serve_exposed(config: &ServerConfig, listener: TcpListener) -> anyhow::Result<()> {
    let db = ExposedDatabase::new(&config.connection_string).await;
    let service = EntitySearchService::new(db.clone(), db);

    let state = AppState {
        entity_search_service: Arc::new(service),
    };
    let router = routes().with_state(state);

    axum::serve(listener, router).await?;

    Ok(())
}
use anyhow::Context;

/// Configuration for the HTTP server.
pub struct ServerConfig {
    /// PostgreSQL connection string.
    pub connection_string: String,
}

impl ServerConfig {
    /// Reads the database connection string from the environment.
    ///
    /// # Errors
    /// Returns an error if `DATABASE_URL` is missing or contains non-Unicode data.
    pub fn from_env() -> anyhow::Result<Self> {
        Ok(Self {
            connection_string: std::env::var("DATABASE_URL").context("DATABASE_URL must be set")?,
        })
    }
}
use std::{fs::File, io::Write, path::PathBuf};

use exposed::{
    domain::models::entity_search::EntitySearchRequest,
    inbound::{
        cli::config::{DeclarationFetcherConfig, FetcherConfig, LoaderConfig},
        http::{config::ServerConfig, server::serve_exposed},
    },
};
use reqwest::StatusCode;
use serde_json::Value;
use tempfile::{NamedTempFile, TempDir};

mod declarations;
pub use declarations::{DeclarationFunding, FundingEntry, read_declaration_funding};

pub struct Guard {
    port: u16,
}

pub async fn search_entities(
    app: &Guard,
    params: &EntitySearchRequest,
) -> anyhow::Result<Vec<Value>> {
    let client = reqwest::Client::new();

    let port = app.port;

    let (term, strictness, entries) = (params.term(), params.strictness(), params.max_entries());
    let url = format!(
        "http://127.0.0.1:{port}/search?term={term}&&strictness={strictness}&&max_entries={entries}"
    );
    let response = client.get(url).send().await?;

    match response.status() {
        StatusCode::OK => {
            let bytes = response.bytes().await?;
            let data: Value = serde_json::from_slice(&bytes)?;
            let entities = data
                .get("entities")
                .and_then(|d| d.as_array())
                .ok_or(anyhow::anyhow!("unparsable"))?
                .to_vec();
            Ok(entities)
        }
        StatusCode::INTERNAL_SERVER_ERROR => Err(anyhow::anyhow!("something unexpected happened")),
        StatusCode::UNPROCESSABLE_ENTITY => Err(anyhow::anyhow!("bad url")),
        _ => Err(anyhow::anyhow!(
            "something really unexpected happened, investigate"
        )),
    }
}

pub async fn start_app() -> anyhow::Result<Guard> {
    let config = ServerConfig::from_env()?;
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await?;
    let port = listener.local_addr()?.port();
    let _handle = tokio::task::spawn(async move {
        let _ = serve_exposed(&config, listener).await;
        println!("started");
    });

    Ok(Guard { port })
}

pub fn cli_fetcher_config(tmp: &TempDir) -> (NamedTempFile<File>, PathBuf) {
    let config = FetcherConfig {
        batch_size: 100,
        data_dir: tmp.path().to_path_buf(),
    };
    let contents = rust_yaml::to_string(&config).unwrap();
    let mut file = tempfile::NamedTempFile::new().unwrap();
    file.write_all(contents.as_bytes()).unwrap();
    let path = file.path().to_path_buf();
    (file, path)
}

pub fn cli_loader_config(tmp: &TempDir, conn_str: &str) -> (NamedTempFile<File>, PathBuf) {
    let config = LoaderConfig {
